"""Camera-guided controller for the single SweetenCoffee episode.
Uses only the public robot client, RGB/depth/calibration and proprioception.
Interactive commands are logged alongside every executed action and observation.
"""
import json, sys, os, time
import numpy as np
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares
from PIL import Image, ImageDraw
from rcb_client import Robot
ROOT='/app/runs'

def fk(q):
    a=[0,0,0,.0825,-.0825,0,.088]
    d=[.333,0,.316,0,.384,0,.107]
    alpha=[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]
    T=np.eye(4)
    for ai,di,al,qi in zip(a,d,alpha,q):
        ca,sa,c,s=np.cos(al),np.sin(al),np.cos(qi),np.sin(qi)
        T=T@np.array([[c,-s,0,ai],[s*ca,c*ca,-sa,-sa*di],[s*sa,c*sa,ca,ca*di],[0,0,0,1]])
    return T

class Controller:
 def __init__(self):
    self.r=Robot();self.spec=self.r.spec();self.i=1
    self.obs=self.r.get_obs(include_depth=True,video='none')
    self.record(self.obs,'connect')
    self.base_R=np.eye(3);self.base_p=np.zeros(3);self.tool_p=np.array([0,0,.097]);self.cam_R=np.eye(3)
    self.samples=[]
 def p(self):return np.array(self.obs.meta['proprio']['now'])
 def record(self,o,note):
    self.obs=o;d=f'{ROOT}/{self.i:03d}';o.save(d)
    ims=[]
    for name in ['robot0_agentview_left','robot0_agentview_center','robot0_agentview_right','robot0_eye_in_hand']:
      if name in o.last:
       im=Image.fromarray(o.last[name]).resize((640,480));ImageDraw.Draw(im).text((8,8),name,fill='yellow');ims.append(im)
    if ims:
      allim=Image.new('RGB',(1280,480*((len(ims)+1)//2)))
      for j,im in enumerate(ims):allim.paste(im,((j%2)*640,(j//2)*480))
      allim.save('/app/output/latest.jpg')
    with open('/app/output/commands.jsonl','a') as f:f.write(json.dumps({'run':self.i,'note':note})+'\n')
    self.i+=1
    p=self.p();print(json.dumps({'run':d,'time_left':o.meta['time_left_s'],'eef':p[26:29].tolist(),'q':p[4:11].tolist(),'fingers':p[11:13].tolist(),'base':p[:4].tolist()}),flush=True)
 def run(self,A,note):
    np.save(f'{ROOT}/actions_{self.i:03d}.npy',A)
    self.record(self.r.submit('joint_position',A,include_depth=True,video='none',note=note),note)
 def joints(self,q=None,grip=None,n=40,base=None,torso=0,mode=-1):
    p=self.p();start=p[4:11];q=start if q is None else np.array(q)
    A=np.zeros((n,13));t=np.linspace(0,1,n);s=3*t*t-2*t*t*t
    A[:,:7]=start+(q-start)*s[:,None];A[:,7]=p[36] if grip is None else grip;A[:,12]=mode
    if base is not None:A[:,8:11]=base
    A[:,11]=torso;self.run(A,'joint move')
 def sample(self):
    p=self.p();C=np.array(self.obs.meta['cameras']['robot0_eye_in_hand']['cam2world_gl'])
    self.samples.append((p[4:11],p[26:29],C[:3,:3]));print('sample',len(self.samples),flush=True)
 def calibrate(self):
    # Fit world frame and tool displacement to measured grip positions.
    def fun(v):
      B=R.from_rotvec(v[:3]).as_matrix();p=v[3:6];tp=v[6:9]
      return np.concatenate([B@(fk(q)[:3,3]+fk(q)[:3,:3]@tp)+p-x for q,x,c in self.samples])
    v=np.r_[0,0,0,self.samples[0][1]-fk(self.samples[0][0])[:3,3],0,0,.097]
    sol=least_squares(fun,v,max_nfev=1000)
    self.base_R=R.from_rotvec(sol.x[:3]).as_matrix();self.base_p=sol.x[3:6];self.tool_p=sol.x[6:9]
    q,x,c=self.samples[-1];self.cam_R=(self.base_R@fk(q)[:3,:3]).T@c
    print('calibration',sol.x,'error',np.linalg.norm(sol.fun),flush=True)
    self.savecal()
 def savecal(self):
    np.savez('/app/output/calibration.npz',base_R=self.base_R,base_p=self.base_p,tool_p=self.tool_p,cam_R=self.cam_R)
 def posrot(self,q):
    F=fk(q);return self.base_R@(F[:3,3]+F[:3,:3]@self.tool_p)+self.base_p,self.base_R@F[:3,:3]@self.cam_R
 def ik(self,xyz,rot=None):
    q0=self.p()[4:11];xyz=np.array(xyz)
    if rot is None:rot=np.array(self.obs.meta['cameras']['robot0_eye_in_hand']['cam2world_gl'])[:3,:3]
    rot=np.array(rot)
    def fun(q):
      p,c=self.posrot(q)
      return np.r_[(p-xyz)*4,R.from_matrix(rot@c.T).as_rotvec(),.012*(q-q0)]
    sol=least_squares(fun,q0,bounds=([-2.9,-1.76,-2.9,-3.07,-2.9,-.01,-2.9],[2.9,1.76,2.9,-.07,2.9,3.75,2.9]),max_nfev=300)
    print('IK',sol.x,'pred',self.posrot(sol.x)[0],'err',sol.fun[:6],flush=True)
    return sol.x
 def cmd(self,c):
    typ=c['cmd']
    if typ=='obs':self.record(self.r.get_obs(seconds=c.get('seconds',0),include_depth=True,video='none'),'observe')
    elif typ=='joint':
      q=c.get('q');
      if 'delta' in c:q=self.p()[4:11]+np.array(c['delta'])
      self.joints(q,c.get('grip'),c.get('n',40),c.get('base'),c.get('torso',0),c.get('mode',-1))
    elif typ=='sample':self.sample()
    elif typ=='calibrate':self.calibrate()
    elif typ=='loadcal':
      f=np.load('/app/output/calibration.npz')
      for k in f.files:setattr(self,k,f[k])
    elif typ=='goto':
      xyz=c.get('xyz',self.p()[26:29]);
      if 'delta' in c:xyz=self.p()[26:29]+np.array(c['delta'])
      q=self.ik(xyz,c.get('rot'));self.joints(q,c.get('grip'),c.get('n',50))
    elif typ=='reanchor':
      q=self.p()[4:11];C=np.array(self.obs.meta['cameras']['robot0_eye_in_hand']['cam2world_gl'])[:3,:3]
      self.base_R=C@self.cam_R.T@fk(q)[:3,:3].T
      F=fk(q);self.base_p=self.p()[26:29]-self.base_R@(F[:3,3]+F[:3,:3]@self.tool_p);self.savecal();print('reanchored',flush=True)
    elif typ=='pixel':
      cam=c.get('cam','robot0_agentview_center');u,v=c['uv'];dep=self.obs.depth[cam];dep=dep[-1] if dep.ndim==3 else dep
      D=float(np.median(dep[max(0,v-1):v+2,max(0,u-1):u+2]));cal=self.obs.meta['cameras'][cam];K=np.array(cal['intrinsic_cv']);C=np.array(cal['cam2world_gl']);p=C@np.r_[(u-K[0,2])*D/K[0,0],-(v-K[1,2])*D/K[1,1],-D,1]
      print('pixel',c,'depth',D,'world',p[:3],flush=True)
    elif typ=='status':print(self.r.status(),flush=True)
if __name__=='__main__':
 ctrl=Controller()
 for line in sys.stdin:
  try:ctrl.cmd(json.loads(line))
  except Exception as e:print(type(e).__name__,str(e),flush=True)
